<?php
namespace App\Http\Controllers;use App\Domain\Products\{ProductIndexViewData,ProductViewData};use Illuminate\Contracts\View\View;use Illuminate\Http\Request;class PublicProductController extends Controller {public function index(Request $r,ProductIndexViewData $d):View{$category=$r->validate(['category'=>['nullable','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/'],'page'=>['nullable','integer','min:1']])['category']??null;$products=$d->get($category,max(1,$r->integer('page',1)));if($products['invalid'])abort(404);return view('products.index',['products'=>$products,'selectedCategory'=>$category]+app(PublicSiteController::class)->sharedViewData($r));}public function show(Request $r,string $product,ProductViewData $d):View{$payload=$d->published($product);if(!$payload)abort(404);return view('products.show',['product'=>$payload,'preview'=>false]+app(PublicSiteController::class)->sharedViewData($r));}}